// Package indeedparse extracts structured job data from Indeed's
// server-rendered HTML. Indeed embeds the full search-result model and
// job-detail data as JSON inside <script> tags (no separate JSON API for the
// public website), so these helpers brace-match the embedded objects out of
// the raw HTML returned by the Surf-backed client and the JSON-LD JobPosting
// block on a viewjob page.
//
// This is hand-authored (no "Generated by CLI Printing Press" header) so it
// survives `generate --force` and regen-merge.
package indeedparse

import (
	"encoding/json"
	"fmt"
	"regexp"
	"strconv"
	"strings"

	"github.com/mvanhorn/printing-press-library/library/productivity/indeed/internal/cliutil"
)

// Job is the clean, agent-facing shape for a search result. It is what gets
// stored in the local resources table (resource_type "job") and emitted by the
// search/find commands.
type Job struct {
	Key           string   `json:"key"`
	Title         string   `json:"title"`
	Company       string   `json:"company"`
	Location      string   `json:"formattedLocation"`
	Remote        bool     `json:"remote"`
	Salary        string   `json:"salary,omitempty"`
	SalaryMin     float64  `json:"salaryMin,omitempty"`
	SalaryMax     float64  `json:"salaryMax,omitempty"`
	SalaryPeriod  string   `json:"salaryPeriod,omitempty"`
	JobTypes      []string `json:"jobTypes,omitempty"`
	Posted        string   `json:"posted,omitempty"`
	CompanyRating float64  `json:"companyRating,omitempty"`
	ReviewCount   int      `json:"reviewCount,omitempty"`
	Snippet       string   `json:"snippet,omitempty"`
	URL           string   `json:"url"`
}

// JobDetail is the clean shape returned by `job get`.
type JobDetail struct {
	Key            string `json:"key"`
	Title          string `json:"title"`
	Company        string `json:"company"`
	Location       string `json:"location,omitempty"`
	Remote         bool   `json:"remote"`
	EmploymentType string `json:"employmentType,omitempty"`
	DatePosted     string `json:"datePosted,omitempty"`
	ValidThrough   string `json:"validThrough,omitempty"`
	Description    string `json:"description"`
	URL            string `json:"url"`
}

const viewJobBase = "https://www.indeed.com/viewjob?jk="

// rawJob mirrors the subset of Indeed's job-card model fields we surface.
type rawJob struct {
	JobKey                string   `json:"jobkey"`
	Title                 string   `json:"title"`
	DisplayTitle          string   `json:"displayTitle"`
	Company               string   `json:"company"`
	FormattedLocation     string   `json:"formattedLocation"`
	RemoteLocation        bool     `json:"remoteLocation"`
	JobTypes              []string `json:"jobTypes"`
	FormattedRelativeTime string   `json:"formattedRelativeTime"`
	CompanyRating         float64  `json:"companyRating"`
	CompanyReviewCount    int      `json:"companyReviewCount"`
	Snippet               string   `json:"snippet"`
	SalarySnippet         struct {
		Text     string `json:"text"`
		Currency string `json:"currency"`
	} `json:"salarySnippet"`
	ExtractedSalary *struct {
		Min  float64 `json:"min"`
		Max  float64 `json:"max"`
		Type string  `json:"type"`
	} `json:"extractedSalary"`
}

var totalJobCountRE = regexp.MustCompile(`"totalJobCount"\s*:\s*(\d+)`)

var (
	blockTagRE   = regexp.MustCompile(`(?is)</(p|div|h[1-6]|tr|ul|ol)>|<br\s*/?>|</li>`)
	listItemRE   = regexp.MustCompile(`(?i)<li[^>]*>`)
	anyTagRE     = regexp.MustCompile(`(?s)<[^>]*>`)
	multiNLRE    = regexp.MustCompile(`\n{3,}`)
	trailingWS   = regexp.MustCompile(`[ \t]+\n`)
	multiSpaceRE = regexp.MustCompile(`[ \t]{2,}`)
)

// cleanBlock turns an HTML fragment into readable multi-line plain text:
// block tags become newlines, <li> becomes a bullet, remaining tags are
// stripped, then entities are unescaped and whitespace is tidied. Use for the
// full job description.
func cleanBlock(s string) string {
	if s == "" {
		return ""
	}
	s = listItemRE.ReplaceAllString(s, "\n- ")
	s = blockTagRE.ReplaceAllString(s, "\n")
	s = anyTagRE.ReplaceAllString(s, "")
	s = cliutil.CleanText(s)
	s = trailingWS.ReplaceAllString(s, "\n")
	s = multiNLRE.ReplaceAllString(s, "\n\n")
	return strings.TrimSpace(s)
}

// cleanInline strips HTML to a single-line snippet (tags → spaces, collapsed).
func cleanInline(s string) string {
	if s == "" {
		return ""
	}
	s = listItemRE.ReplaceAllString(s, " ")
	s = blockTagRE.ReplaceAllString(s, " ")
	s = anyTagRE.ReplaceAllString(s, " ")
	s = cliutil.CleanText(s)
	s = strings.ReplaceAll(s, "\n", " ")
	s = multiSpaceRE.ReplaceAllString(s, " ")
	return strings.TrimSpace(s)
}

// ExtractBracedObject finds anchor in s, then returns the JSON object that
// starts at the first '{' at or after the anchor, brace-matched while
// respecting string literals and escapes. ok is false if the anchor is not
// found or no balanced object follows it.
func ExtractBracedObject(s, anchor string) (string, bool) {
	ai := strings.Index(s, anchor)
	if ai < 0 {
		return "", false
	}
	start := strings.IndexByte(s[ai:], '{')
	if start < 0 {
		return "", false
	}
	start += ai
	depth := 0
	inStr := false
	esc := false
	for i := start; i < len(s); i++ {
		c := s[i]
		if esc {
			esc = false
			continue
		}
		if c == '\\' {
			esc = true
			continue
		}
		if c == '"' {
			inStr = !inStr
			continue
		}
		if inStr {
			continue
		}
		switch c {
		case '{':
			depth++
		case '}':
			depth--
			if depth == 0 {
				return s[start : i+1], true
			}
		}
	}
	return "", false
}

// ParseSearchResults extracts the job-card results and the total job count
// from a /jobs search-results HTML page. totalJobCount is best-effort (0 when
// absent from the page).
func ParseSearchResults(html []byte) ([]Job, int, error) {
	s := string(html)
	obj, ok := ExtractBracedObject(s, `"mosaicProviderJobCardsModel":`)
	if !ok {
		if looksBlocked(s) {
			return nil, 0, fmt.Errorf("indeed returned a challenge/blocked page instead of results (bot protection may have escalated)")
		}
		return nil, 0, fmt.Errorf("could not locate job results in page (Indeed markup may have changed)")
	}
	var model struct {
		Results []rawJob `json:"results"`
	}
	if err := json.Unmarshal([]byte(obj), &model); err != nil {
		return nil, 0, fmt.Errorf("parsing job-card model: %w", err)
	}
	total := 0
	if m := totalJobCountRE.FindStringSubmatch(s); m != nil {
		total, _ = strconv.Atoi(m[1])
	}
	jobs := make([]Job, 0, len(model.Results))
	for _, r := range model.Results {
		if r.JobKey == "" {
			continue
		}
		jobs = append(jobs, r.toJob())
	}
	return jobs, total, nil
}

func (r rawJob) toJob() Job {
	title := r.Title
	if title == "" {
		title = cliutil.CleanText(r.DisplayTitle)
	}
	j := Job{
		Key:           r.JobKey,
		Title:         cliutil.CleanText(title),
		Company:       cliutil.CleanText(r.Company),
		Location:      cliutil.CleanText(r.FormattedLocation),
		Remote:        r.RemoteLocation,
		JobTypes:      r.JobTypes,
		Posted:        r.FormattedRelativeTime,
		CompanyRating: r.CompanyRating,
		ReviewCount:   r.CompanyReviewCount,
		Snippet:       cleanInline(r.Snippet),
		URL:           viewJobBase + r.JobKey,
	}
	// Salary: prefer the structured extractedSalary, fall back to parsing the
	// free-text snippet.
	if r.ExtractedSalary != nil && (r.ExtractedSalary.Min > 0 || r.ExtractedSalary.Max > 0) {
		j.SalaryMin = r.ExtractedSalary.Min
		j.SalaryMax = r.ExtractedSalary.Max
		j.SalaryPeriod = normalizePeriod(r.ExtractedSalary.Type)
		j.Salary = cliutil.CleanText(r.SalarySnippet.Text)
	} else if r.SalarySnippet.Text != "" {
		j.Salary = cliutil.CleanText(r.SalarySnippet.Text)
		min, max, period := ParseSalary(j.Salary)
		j.SalaryMin = min
		j.SalaryMax = max
		j.SalaryPeriod = period
	}
	return j
}

func normalizePeriod(t string) string {
	switch strings.ToUpper(t) {
	case "YEARLY", "YEAR", "ANNUAL":
		return "year"
	case "HOURLY", "HOUR":
		return "hour"
	case "MONTHLY", "MONTH":
		return "month"
	case "WEEKLY", "WEEK":
		return "week"
	case "DAILY", "DAY":
		return "day"
	default:
		return strings.ToLower(t)
	}
}

var (
	salaryNumRE = regexp.MustCompile(`\$?\s*([\d][\d,]*(?:\.\d+)?)\s*([KkMm]?)`)
	periodRE    = regexp.MustCompile(`(?i)\b(year|hour|month|week|day|annually|annual|yr|hr)\b`)
)

// ParseSalary parses Indeed's free-text salary snippets like
// "$55 an hour", "$100,000 - $130,000 a year", "Up to $90K a year".
// Returns 0/0 when no figure is found.
func ParseSalary(text string) (min, max float64, period string) {
	if text == "" {
		return 0, 0, ""
	}
	matches := salaryNumRE.FindAllStringSubmatch(text, -1)
	var nums []float64
	for _, m := range matches {
		raw := strings.ReplaceAll(m[1], ",", "")
		v, err := strconv.ParseFloat(raw, 64)
		if err != nil {
			continue
		}
		switch strings.ToUpper(m[2]) {
		case "K":
			v *= 1_000
		case "M":
			v *= 1_000_000
		}
		nums = append(nums, v)
	}
	if pm := periodRE.FindString(text); pm != "" {
		period = normalizePeriod(pm)
	}
	switch len(nums) {
	case 0:
		return 0, 0, period
	case 1:
		return nums[0], nums[0], period
	default:
		return nums[0], nums[len(nums)-1], period
	}
}

// jsonLDScriptRE matches the contents of <script type="application/ld+json">…</script>.
var jsonLDScriptRE = regexp.MustCompile(`(?s)<script[^>]*type="application/ld\+json"[^>]*>(.*?)</script>`)

// jobPosting models the W3C JobPosting JSON-LD schema Indeed emits on viewjob.
type jobPosting struct {
	Type            string          `json:"@type"`
	Title           string          `json:"title"`
	Description     string          `json:"description"`
	DatePosted      string          `json:"datePosted"`
	ValidThrough    string          `json:"validThrough"`
	EmploymentType  json.RawMessage `json:"employmentType"`
	JobLocationType string          `json:"jobLocationType"`
	HiringOrg       struct {
		Name string `json:"name"`
	} `json:"hiringOrganization"`
	JobLocation json.RawMessage `json:"jobLocation"`
}

// ParseJobDetail extracts the full job detail from a /viewjob HTML page. It
// prefers the JSON-LD JobPosting block (a stable W3C schema) and falls back to
// the embedded sanitizedJobDescription for the description body when needed.
func ParseJobDetail(html []byte, key string) (*JobDetail, error) {
	s := string(html)
	var jp *jobPosting
	for _, m := range jsonLDScriptRE.FindAllStringSubmatch(s, -1) {
		var candidate jobPosting
		if err := json.Unmarshal([]byte(strings.TrimSpace(m[1])), &candidate); err != nil {
			continue
		}
		if strings.EqualFold(candidate.Type, "JobPosting") {
			jp = &candidate
			break
		}
	}
	if jp == nil {
		if looksBlocked(s) {
			return nil, fmt.Errorf("indeed returned a challenge/blocked page instead of the job (bot protection may have escalated)")
		}
		return nil, fmt.Errorf("could not find job detail on page (it may be expired or the job key is wrong)")
	}
	d := &JobDetail{
		Key:            key,
		Title:          cliutil.CleanText(jp.Title),
		Company:        cliutil.CleanText(jp.HiringOrg.Name),
		DatePosted:     jp.DatePosted,
		ValidThrough:   jp.ValidThrough,
		EmploymentType: decodeEmploymentType(jp.EmploymentType),
		Remote:         strings.EqualFold(jp.JobLocationType, "TELECOMMUTE"),
		URL:            viewJobBase + key,
	}
	d.Location = decodeJobLocation(jp.JobLocation, d.Remote)
	// Description: JSON-LD carries the full HTML body; fall back to the
	// embedded sanitizedJobDescription if it's empty.
	desc := cleanBlock(jp.Description)
	if desc == "" {
		if sd := extractJSONString(s, `"sanitizedJobDescription":`); sd != "" {
			desc = cleanBlock(sd)
		}
	}
	d.Description = desc
	return d, nil
}

// decodeEmploymentType handles employmentType being a string or an array of strings.
func decodeEmploymentType(raw json.RawMessage) string {
	if len(raw) == 0 {
		return ""
	}
	var one string
	if json.Unmarshal(raw, &one) == nil {
		return one
	}
	var many []string
	if json.Unmarshal(raw, &many) == nil {
		return strings.Join(many, ", ")
	}
	return ""
}

// decodeJobLocation pulls a human-readable location out of the JSON-LD
// jobLocation, which may be an object, an array of objects, or absent.
func decodeJobLocation(raw json.RawMessage, remote bool) string {
	type place struct {
		Address struct {
			Locality string `json:"addressLocality"`
			Region   string `json:"addressRegion"`
			Country  string `json:"addressCountry"`
		} `json:"address"`
	}
	fmtPlace := func(p place) string {
		parts := []string{}
		if p.Address.Locality != "" {
			parts = append(parts, p.Address.Locality)
		}
		if p.Address.Region != "" {
			parts = append(parts, p.Address.Region)
		}
		return strings.Join(parts, ", ")
	}
	if len(raw) > 0 {
		var one place
		if json.Unmarshal(raw, &one) == nil {
			if loc := fmtPlace(one); loc != "" {
				return loc
			}
		}
		var many []place
		if json.Unmarshal(raw, &many) == nil {
			for _, p := range many {
				if loc := fmtPlace(p); loc != "" {
					return loc
				}
			}
		}
	}
	if remote {
		return "Remote"
	}
	return ""
}

// extractJSONString returns the JSON string value that follows anchor (which
// must end at the colon, e.g. `"field":`). It correctly unescapes the JSON
// string literal. Returns "" if not found.
func extractJSONString(s, anchor string) string {
	ai := strings.Index(s, anchor)
	if ai < 0 {
		return ""
	}
	rest := s[ai+len(anchor):]
	q := strings.IndexByte(rest, '"')
	if q < 0 {
		return ""
	}
	// Walk from the opening quote, collecting until the matching close quote,
	// then let encoding/json unescape the literal.
	esc := false
	for i := q + 1; i < len(rest); i++ {
		c := rest[i]
		if esc {
			esc = false
			continue
		}
		if c == '\\' {
			esc = true
			continue
		}
		if c == '"' {
			var out string
			if err := json.Unmarshal([]byte(rest[q:i+1]), &out); err == nil {
				return out
			}
			return ""
		}
	}
	return ""
}

func looksBlocked(s string) bool {
	head := s
	if len(head) > 4000 {
		head = head[:4000]
	}
	lower := strings.ToLower(head)
	for _, marker := range []string{"just a moment", "cf-mitigated", "verifying you are human", "access denied", "attention required"} {
		if strings.Contains(lower, marker) {
			return true
		}
	}
	return false
}
